Given a number positive number n, find value of f0 + f1 + f2 + .... + fn where fi indicates i'th Fibonacci number. Remember that f0 = 0, f1 = 1, f2 = 1, f3 = 2, f4 = 3, f5 = 5, ... Examples : Input  : n = 3Output : 4Explanation : 0 + 1 + 1 + 2  = 4Input  :  n = 4Output :  7Explanation : 0 + 1 + 1 + 2 + 3  = 7Try It YourselfTable of Content[Naive Approach] By storing all Fibonacci numbers - O(n) time and O(n) space[Better Approach]  Space Optimized - O(n) time and O(1) space[Expected Approach] Efficient Fibonacci Sum Calculation - O(log(n)) time and O(n) space[Naive Approach] By storing all Fibonacci numbers - O(n) time and O(n) spaceThe idea is simple we will first generate all Fibonacci numbers up to a given number n, then compute and print the sum of these Fibonacci numbers.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int calculateSum(int n)
{
    if (n <= 0)
       return 0;

    vector<int> fibo(n+1);
    fibo[0] = 0, fibo[1] = 1;

    // Initialize result
    int sum = fibo[0] + fibo[1];

    // Add remaining terms
    for (int i=2; i<=n; i++)
    {
        fibo[i] = fibo[i-1]+fibo[i-2];
        sum += fibo[i];
    }

    return sum;
}

int main()
{
    int n = 4;
    cout << calculateSum(n) << endl;
    return 0;
}


