int calculateSum(int n)
{
    int a = 0, b = 0, sumf = 1;

    // Edge Case When n is 0
    if (n <= 0)
        return 0;

    int curr = 1;
    for (int i = 2; i <= n; i++)
    {
        // update a,b and curr
        a = b;
        b = curr;
        curr = a + b;
        sumf += curr;
    }

    return sumf;
}

